class TreeNode<T> {
    T value;
    TreeNode<T> left;
    TreeNode<T> right;

    TreeNode(T value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    Objects.requireNonNull(node, "Node cannot be null");
    TreeNode<T> newParent = node.left;
    if (newParent == null) {
        return node; // No left child to rotate with
    }
    TreeNode<T> rightChildOfNewParent = newParent.right;
    newParent.right = node;
    node.left = rightChildOfNewParent;
    return newParent;
}

