import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public class TypeResolver {
    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
            for (int i = 0; i < actualTypeArguments.length; i++) {
                if (actualTypeArguments[i] instanceof Class) {
                    resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
                } else {
                    return null; // Cannot resolve type argument
                }
            }
            return resolvedArguments;
        }
        return null; // Not parameterized
    }

    public static void main(String[] args) {
        // Example usage
        Type genericType = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{String.class, Integer.class};
            }

            @Override
            public Type getRawType() {
                return Object.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };

        Class<?>[] arguments = resolveArguments(genericType, Object.class);
        if (arguments != null) {
            for (Class<?> arg : arguments) {
                System.out.println(arg.getName());
            }
        } else {
            System.out.println("Arguments could not be resolved or genericType is not parameterized.");
        }
    }
}

