class Bucket {
    private Bucket next;
    private Bucket prev;

    public void insertBefore(Bucket bucket) {
        if (bucket == null) {
            return;
        }
        this.prev = bucket.prev;
        this.next = bucket;
        if (bucket.prev != null) {
            bucket.prev.next = this;
        }
        bucket.prev = this;
    }

    public Bucket getNext() {
        return next;
    }

    public void setNext(Bucket next) {
        this.next = next;
    }

    public Bucket getPrev() {
        return prev;
    }

    public void setPrev(Bucket prev) {
        this.prev = prev;
    }

    public static void main(String[] args) {
        Bucket bucket1 = new Bucket();
        Bucket bucket2 = new Bucket();
        Bucket bucket3 = new Bucket();

        bucket1.setNext(bucket2);
        bucket2.setPrev(bucket1);

        bucket3.insertBefore(bucket2);

        // Now the order should be: bucket1 -> bucket3 -> bucket2
        System.out.println(bucket1.getNext() == bucket3); // true
        System.out.println(bucket3.getPrev() == bucket1); // true
        System.out.println(bucket3.getNext() == bucket2); // true
        System.out.println(bucket2.getPrev() == bucket3); // true
    }
}

