    public Mappings(Map<String, Object> fields) {
        this.fields = fields;
    }

    public Map<String, Object> getFields() {
        return fields;
    }

    public Mappings diffStructure(String tableName, Mappings mappings) {
        Map<String, Object> diff = new HashMap<>();
        Map<String, Object> currentFields = this.getFields();
        Map<String, Object> inputFields = mappings.getFields();

        for (Map.Entry<String, Object> entry : currentFields.entrySet()) {
            String key = entry.getKey();
            if (!inputFields.containsKey(key) && !"_source".equals(key)) {
                diff.put(key, entry.getValue());
            }
        }

        return new Mappings(diff);
    }

    public static void main(String[] args) {
        Map<String, Object> currentFields = new HashMap<>();
        currentFields.put("field1", "value1");
        currentFields.put("field2", "value2");
        currentFields.put("_source", "sourceValue");

        Map<String, Object> inputFields = new HashMap<>();
        inputFields.put("field1", "value1");

        Mappings currentMappings = new Mappings(currentFields);
        Mappings inputMappings = new Mappings(inputFields);

        Mappings diffMappings = currentMappings.diffStructure("tableName", inputMappings);
        System.out.println(diffMappings.getFields());
    }
}

