import java.util.Properties;

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return substituteVariables(value, props);
}

private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int start = 0;
    int end;
    while ((end = value.indexOf("${", start)) != -1) {
        result.append(value.substring(start, end));
        start = end + 2;
        end = value.indexOf("}", start);
        if (end == -1) {
            break;
        }
        String varName = value.substring(start, end);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        }
        start = end + 1;
    }
    result.append(value.substring(start));
    return result.toString();
}

