public static Entry<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    Vec2 center = box.getCenter();
    float halfWidth = box.getWidth() / 4.0f; // Half of the original half-width
    float height = box.getHeight();
    float angle = box.getAngle();

    Vec2 center1 = new Vec2(center.x - halfWidth, center.y);
    Vec2 center2 = new Vec2(center.x + halfWidth, center.y);

    Box2D box1 = new Box2D();
    box1.setAsBox(halfWidth, height, center1, angle);

    Box2D box2 = new Box2D();
    box2.setAsBox(halfWidth, height, center2, angle);

    return new SimpleEntry<>(box1, box2);
}

