public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= length) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '"':
                    output.append('"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= length) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    int value = 0;
                    for (int j = 0; j < 4; j++) {
                        c = str.charAt(++i);
                        switch (c) {
                            case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
                                value = (value << 4) + c - '0';
                                break;
                            case 'a': case 'b': case 'c': case 'd': case 'e': case 'f':
                                value = (value << 4) + 10 + c - 'a';
                                break;
                            case 'A': case 'B': case 'C': case 'D': case 'E': case 'F':
                                value = (value << 4) + 10 + c - 'A';
                                break;
                            default:
                                throw new Exception("Invalid unicode escape sequence");
                        }
                    }
                    output.append((char) value);
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

