import java.io.DataInputStream;
import java.io.IOException;

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try (DataInputStream dis = new DataInputStream(new java.io.ByteArrayInputStream(classFileBuffer))) {
        // Skip to the start of the constant pool entry
        dis.skipBytes(8); // Skip magic, minor_version, major_version
        int constantPoolCount = dis.readUnsignedShort();
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = dis.readUnsignedByte();
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    dis.skipBytes(dis.readUnsignedShort());
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    dis.skipBytes(4);
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    dis.skipBytes(8);
                    i++; // These take up two entries
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                case 16: // CONSTANT_MethodType
                    dis.skipBytes(2);
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                case 18: // CONSTANT_InvokeDynamic
                    dis.skipBytes(4);
                    break;
                default:
                    throw new IOException("Unknown constant pool tag: " + tag);
            }
        }
        // Read the CONSTANT_Utf8 entry
        if (dis.readUnsignedByte() != 1) {
            throw new IOException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
        }
        int length = dis.readUnsignedShort();
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("charBuffer is not large enough to hold the string");
        }
        for (int i = 0; i < length; i++) {
            charBuffer[i] = dis.readChar();
        }
        return new String(charBuffer, 0, length);
    } catch (IOException e) {
        throw new RuntimeException("Error reading UTF8 string from constant pool", e);
    }
}

