class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

class LinkedListImpl<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }

        E element = node.item;
        ListNodeImpl<E> next = node.next;
        ListNodeImpl<E> prev = node.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            node.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            node.next = null;
        }

        node.item = null;
        size--;
        return true;
    }
}

