private void pop(final String descriptor) {
    Stack<Object> outputFrameStack = new Stack<>();
    int index = 0;
    while (index < descriptor.length()) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
            case 'F':
                outputFrameStack.pop();
                index++;
                break;
            case 'D':
            case 'J':
                outputFrameStack.pop();
                outputFrameStack.pop();
                index++;
                break;
            case 'L':
                int endIndex = descriptor.indexOf(';', index);
                if (endIndex != -1) {
                    outputFrameStack.pop();
                    index = endIndex + 1;
                } else {
                    index++;
                }
                break;
            case '[':
                outputFrameStack.pop();
                index++;
                break;
            case '(':
                index++;
                while (descriptor.charAt(index) != ')') {
                    pop(String.valueOf(descriptor.charAt(index)));
                    index++;
                }
                index++;
                break;
            default:
                index++;
                break;
        }
    }
}

