import java.io.File;

public class FileUtils {
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparator = indexOfLastSeparator(filename);
        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1 || lastSeparator > lastDot) {
            return -1;
        }
        return lastDot;
    }

    private static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        System.out.println(indexOfExtension("example.txt")); // Output: 7
        System.out.println(indexOfExtension("example")); // Output: -1
        System.out.println(indexOfExtension("example/file.txt")); // Output: 11
        System.out.println(indexOfExtension("example\\file.txt")); // Output: 11
        System.out.println(indexOfExtension("example/file.")); // Output: 11
        System.out.println(indexOfExtension("example/file.txt.")); // Output: 11
        System.out.println(indexOfExtension("example/file.txt/")); // Output: -1
        System.out.println(indexOfExtension("example\\file.txt\\")); // Output: -1
        System.out.println(indexOfExtension(null)); // Output: -1
    }
}

