import java.util.List;

public class CustomAppender extends AppenderSkeleton {
    private List<java.io.PrintWriter> clients;

    public CustomAppender(List<java.io.PrintWriter> clients) {
        this.clients = clients;
    }

    protected void append(LoggingEvent event) {
        for (java.io.PrintWriter client : clients) {
            client.println(this.layout.format(event));
            client.flush();
        }
    }

    public void close() {
        for (java.io.PrintWriter client : clients) {
            client.close();
        }
    }

    public boolean requiresLayout() {
        return true;
    }
}

